if (-not $documents -or -not (Test-Path -LiteralPath $documents -PathType Container)) { throw 'STOPP: Dokumenter-mappen mangler.' }
$root = Join-Path $documents 'ProgressPal-Git-M06'
$repo = Join-Path $root 'pamelding'
